before.content:
try {
    this.keyResolver = java.util.Objects.requireNonNull(keyResolver, "keyResolver");
    this.random = java.util.Objects.requireNonNull(random, "random");
    connection = DriverManager.getConnection("jdbc:sqlite:" + database.toAbsolutePath());
    try (var statement = connection.createStatement()) {
        statement.execute("PRAGMA journal_mode=WAL");
        statement.execute("PRAGMA synchronous=FULL");
        statement.execute("""
                CREATE TABLE IF NOT EXISTS provider_credentials (
                  credential_id TEXT PRIMARY KEY,
                  revision INTEGER NOT NULL CHECK (revision > 0),
                  key_id TEXT NOT NULL,
                  nonce BLOB NOT NULL CHECK (length(nonce) = 12),
                  ciphertext BLOB NOT NULL,
                  auth_tag BLOB NOT NULL CHECK (length(auth_tag) = 16),
                  updated_at TEXT NOT NULL
                ) STRICT
                """);
    }
} catch (SQLException exception) {
    throw storeFailure("credential database initialization failed", exception);
}

after.content:
try {
    this.keyResolver = java.util.Objects.requireNonNull(keyResolver, "keyResolver");
    this.random = java.util.Objects.requireNonNull(random, "random");
    Path file = database.toAbsolutePath().normalize();
    CredentialDatabaseMigrations.migrate(file);
    connection = DriverManager.getConnection("jdbc:sqlite:" + file);
    try (var statement = connection.createStatement()) {
        statement.execute("PRAGMA journal_mode=WAL");
        statement.execute("PRAGMA synchronous=FULL");
    }
} catch (io.github.diodeme.ji.storage.sqlite.SqliteMigrationException exception) {
    throw storeFailure("credential database migration failed", exception);
} catch (SQLException exception) {
    throw storeFailure("credential database initialization failed", exception);
}
